// Random walk per farm and sensor type, kept in flow context between ticks.
const farms = flow.get('farms') || [];
const state = flow.get('sensorState') || {};
const forceDry = flow.get('forceDry') === true;
flow.set('forceDry', false);

const ranges = {
    humidity: { min: 0, max: 100, start: 55, step: 2 },
    temperature: { min: -50, max: 70, start: 20, step: 0.5 }
};

function uuid() {
    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
        const r = Math.random() * 16 | 0;
        return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
    });
}

const clamp = (value, range) => Math.min(range.max, Math.max(range.min, value));
const messages = [];

for (const farm of farms) {
    for (const type of Object.keys(ranges)) {
        const range = ranges[type];
        const key = farm.farmId + ':' + type;
        let value = state[key] ?? range.start;

        value += (Math.random() * 2 - 1) * range.step;

        // Now and then the soil dries out (about once every 40 ticks), which should raise an alert.
        if (type === 'humidity' && (forceDry || Math.random() < 0.025)) {
            value = 20 + Math.random() * 8;
        }

        // Drift back towards normal values after an anomaly.
        value += (range.start - value) * 0.05;
        value = clamp(value, range);
        state[key] = value;

        messages.push({
            routingKey: 'farm.' + farm.farmId + '.' + type,
            payload: {
                messageId: uuid(),
                farmId: farm.farmId,
                sensorId: farm.sensorId || 'sim',
                type: type,
                value: Math.round(value * 10) / 10,
                timestamp: new Date().toISOString()
            }
        });
    }
}

flow.set('sensorState', state);
node.status({ fill: 'green', shape: 'dot', text: messages.length + ' reading(s) at ' + new Date().toLocaleTimeString() });
return [messages];
